const f = $input.first().json;
const id = require('crypto').randomUUID();
const val = (...keys) => {
  for (const key of keys) if (f[key] !== undefined) return f[key];
  return '';
};
const trim = (v) => { const s = String(v || '').trim(); return s || null; };
const dropAuto = (v) => { const s = String(v || '').trim(); return (s && s !== 'Auto') ? s : null; };

return [{ json: {
  runId: id,
  runMode: 'form',
  topic: String(val('topic', 'Topic')).trim(),
  topicDetail: String(val('topic_detail', 'Topic Detail')).trim(),
  targetKeyword: trim(val('target_keyword', 'Target Keyword')),
  categoryHint: dropAuto(val('category_hint', 'Category Hint')),
  keyEntitiesSeed: trim(val('key_entities', 'Key Entities')),
  faqSeed: trim(val('faq_seed', 'FAQ Seed')),
  wordCountTarget: dropAuto(val('word_count_target', 'Word Count Target')),
  language: String(val('language', 'Language') || 'Indonesia').trim(),
  researchMode: String(val('research_mode', 'Research Mode') || 'Auto').trim(),
  publishMode: String(val('run_mode', 'Run Mode') || 'Live Run - Draft').trim(),
  relatedArticleUrl: trim(val('related_article_url', 'Related Article URL')),
  startedAt: new Date().toISOString()
} }];

