const ctx = JSON.parse(raw);
return [{ json: { contentContext: ctx } }];

const a = $('Code: Set Form Run Context').first().json;
const b = $('Code: Load Content Context').first().json;
let merged = { ...a, contentContext: b.contentContext };

if (merged.publishMode === 'Test') {
  merged.wordCountTarget = '300';
  merged.researchMode = 'Concept Only';
}

return [{ json: merged }];

const d = $input.first().json;
const niche = d.contentContext?.site?.niche || '';
const topic = d.topic || '';
const prompt = `Kamu adalah content policy classifier. Nilai apakah topik berikut layak dijadikan
artikel blog publik.

TOPIK: ${topic}
NICHE SITUS: ${niche}

Tolak (allowed: false) bila topik:
- mengandung ujaran kebencian, kekerasan eksplisit, atau konten seksual
- meminta nasihat medis/hukum/finansial spesifik yang butuh lisensi profesional
- promosi produk ilegal, penipuan, atau klaim kesehatan tidak berdasar
- sama sekali di luar niche situs (tidak relevan bagi pembaca)

CONTOH KHUSUS NICHE FILSAFAT/PSIKOLOGI (CP 002):
- ✅ ALLOWED: "Perspektif filosofis tentang kenapa penderita ADHD sering ditulis ulang
  identitasnya lewat diagnosis" — opini/perspektif umum, bukan permintaan personal.
- ❌ REJECTED: "Bagaimana cara mengobati ADHD saya" / "Obat apa yang cocok untuk kecemasan
  saya" — permintaan saran klinis personal, butuh profesional berlisensi.

Balas HANYA JSON:
{"allowed": boolean, "reason": "<1 kalimat>", "severity": "none|low|high"}`;

return [{ json: { _guardBody: {
  model: 'openai/gpt-oss-120b',
  reasoning_effort: 'low',
  messages: [
    { role: 'system', content: prompt },
    { role: 'user', content: topic }
  ],
  max_tokens: 3000,
  temperature: 0,
  stream: false,
  response_format: { type: 'json_object' }
}} }];

const responseContent = $json.choices?.[0]?.message?.content || $json.content || '';

function parseJson(value) {
  if (value && typeof value === 'object') return value;

  let text = String(value || '')
    .replace(/```json?/gi, '')
    .replace(/```/g, '')
    .trim();
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start !== -1 && end !== -1 && end > start) {
    text = text.substring(start, end + 1);
  }

  try {
    return JSON.parse(text);
  } catch (error) {
    return null;
  }
}

const parsed = parseJson(responseContent);
const allowed = parsed?.allowed === true;
const reason = String(parsed?.reason || (allowed ? 'Allowed' : 'Rejected')).trim();
const severity = String(parsed?.severity || (allowed ? 'low' : 'high')).trim();

return [{
  json: {
    guard_allowed: allowed ? '1' : '0',
    guard_reason: reason,
    guard_severity: severity,
    guard_result: { allowed, reason, severity }
  }
}];

const d = $('Code: Build Run Context').first().json;
const today = new Date().toISOString().split('T')[0];
const keyword = d.targetKeyword || '';
const topicDetail = d.topicDetail || '';
const brief = $input.first().json || {};
const empiricalClaims = Array.isArray(brief.empiricalClaims) ? brief.empiricalClaims : [];
const fallbackSeeds = (brief.sectionSeeds || []).filter(s => s.evidenceType === 'empirical').map(s => s.question);
const searchTargets = empiricalClaims.length > 0
  ? empiricalClaims.map((ec, i) => `${i + 1}. ${ec.claim} — query: ${ec.searchQuery}`).join('\n')
  : (fallbackSeeds.length > 0
      ? fallbackSeeds.map((q, i) => `${i + 1}. ${q}`).join('\n')
      : `${d.topic} (Concept Brief menilai topik ini murni konseptual — cari HANYA data pendukung yang benar-benar relevan, JANGAN memaksakan angka kalau tidak ada yang otoritatif)`);
const targetFactCount = empiricalClaims.length > 0 ? `${empiricalClaims.length}-12` : '3-5';
const numericExpectation = empiricalClaims.length > 0 ? 'minimal 3' : 'sebisa mungkin 1';
const keyEntities = d.keyEntitiesSeed || '';
const sourceLanguage = d.sourceLanguage || null;
let sourceLanguageInstruction = '';
if (sourceLanguage === 'International') sourceLanguageInstruction = '\n\nINSTRUKSI BAHASA SUMBER: WAJIB memprioritaskan sumber berbahasa Inggris/internasional (jurnal akademik, situs institusi .edu/.gov, publikasi riset seperti PMC/Nature/BMC/APA). JANGAN memakai blog SEO atau media populer sebagai sumber utama.';
else if (sourceLanguage === 'Force Indonesia') sourceLanguageInstruction = '\n\nINSTRUKSI BAHASA SUMBER: WAJIB mencari dan memakai sumber berbahasa Indonesia. Gunakan kebebasan penuh dalam memilih sumber — media, jurnal, institusi, riset, apa pun yang paling relevan dan kredibel untuk topik ini, selama berbahasa Indonesia.';
else if (sourceLanguage === 'Bilingual') sourceLanguageInstruction = '\n\nINSTRUKSI BAHASA SUMBER: WAJIB mengumpulkan campuran sumber internasional/akademik DAN sumber Indonesia — targetkan minimal 2-3 fakta per kelompok bahasa.';

const prompt = `Kamu adalah research assistant. Kumpulkan fakta terverifikasi untuk artikel tentang:

TOPIK: ${d.topic}
DETAIL TOPIK: ${topicDetail || 'Tidak ada detail tambahan'}
TARGET KEYWORD: ${keyword || 'Tidak ada'}
ENTITAS WAJIB DIRISET: ${keyEntities || 'Tidak ada'}
TANGGAL HARI INI: ${today}${sourceLanguageInstruction}

Gunakan web search UNTUK KLAIM SPESIFIK BERIKUT:
${searchTargets}

Aturan wajib:
- Setiap fakta HARUS punya sumber dengan nama organisasi/publikasi + URL.
- Prioritaskan data 24 bulan terakhir. Kalau data terbaik lebih lama, sebutkan tahunnya.
- Kumpulkan ${targetFactCount} fakta, ${numericExpectation} di antaranya mengandung angka konkret
  (persentase, jumlah, durasi, harga).
- JANGAN menulis angka yang tidak kamu temukan di sumber. Kalau tidak menemukan data
  numerik untuk suatu aspek, tulis fakta kualitatif dan set "hasNumber": false.
- Sertakan 2-4 pertanyaan yang paling sering ditanyakan orang tentang topik ini
  (untuk bahan FAQ section).
- JANGAN menulis kalimat pembuka/penjelasan apa pun. Balasan HARUS langsung dimulai
  dengan karakter '{' dan diakhiri '}' - tidak ada teks lain sebelum atau sesudahnya.

Balas HANYA JSON:
{
  "facts": [
    {"claim": "<1 kalimat faktual>", "hasNumber": bool, "value": "<angka+unit|null>",
     "sourceName": "<nama organisasi>", "sourceUrl": "<url>", "year": <number|null>}
  ],
  "commonQuestions": ["<pertanyaan>"],
  "entities": ["<nama kunci yang harus disebut eksplisit>"],
  "notes": "<gap riset kalau ada>"
}`;

return [{ json: {
  _researchBody: {
    model: 'tencent/hy3-preview:online',
    reasoning_effort: 'medium',
    messages: [
      { role: 'system', content: 'Anda adalah research assistant. Cari fakta terverifikasi dari web. Balas HANYA JSON valid tanpa markdown, tanpa kalimat pembuka apa pun.' },
      { role: 'user', content: prompt }
    ],
    max_tokens: 16000,
    temperature: 0.3,
    response_format: { type: 'json_object' }
  }
}}];

const ctx = $('Code: Build Run Context').first().json;
const outline = $input.first().json;
const research = $('Code: Normalize Research Payload').first().json;
const facts = research?.facts || [];
const cb = research?.conceptBrief || {};
const language = ctx.language || 'Indonesia';
const tw = outline.totalTargetWords || ctx.contentContext?.geo?.targetWordCount || 1500;
const factsText = facts.slice(0, 12).map((f, i) => `${i + 1}. ${f.claim}${f.value ? ' (' + f.value + ')' : ''} — ${f.sourceName}: ${f.sourceUrl}`).join('
');
const primarySources = Array.isArray(cb.primarySources) ? cb.primarySources.map((s, i) => `${i + 1}. ${s.author || ''}. ${s.title || ''} (${s.year || 'tahun tidak tersedia'}) — ${s.relevance || ''}`).join('
') : '';
const sectionText = (outline.sections || []).map((s, i) => `${i + 1}. ## ${s.heading}
CLAIM: ${s.sectionClaim}
MOVE: ${s.logicalMove?.type} | FROM: ${s.logicalMove?.from} | TO: ${s.logicalMove?.to}`).join('

');
const briefsText = JSON.stringify(outline.sectionBriefs || []);
const faqText = (outline.faq || []).map(q => `### ${q.question}
${q.shortAnswer || ''}`).join('

');
const tone = ctx.contentContext?.tone || {};
const toneText = ['voice: ' + (tone.voice || 'reflective'), 'person: ' + (tone.person || 'contextual'), 'stance: ' + (tone.stance || 'take a defensible position'), 'avoid: ' + (tone.avoid || []).join('; '), 'prefer: ' + (tone.prefer || []).join('; ')].join('
');
const prompt = `Kamu menulis artikel esai reflektif dalam Bahasa ${language}, bukan jawaban chatbot dan bukan artikel teknis ensiklopedis.

=== KONTEKS ARGUMEN ===
JUDUL: ${outline.workingTitle}
LEDE: ${outline.lede}
THESIS: ${outline.thesis}
CLOSING: ${outline.closing}
CLOSING DELTA: ${outline.closingDelta}
ARGUMENT PATTERN: ${cb.argumentPattern || ''}
EXPECTED INSIGHT: ${cb.expectedInsight || ''}
OBJECTION: ${JSON.stringify(outline.objection || {})}

=== OUTLINE DAN LOGICAL MOVE ===
${sectionText}

=== BRIEF PLANNER ===
${briefsText}

=== FAKTA + SUMBER ===
${factsText || '(tidak ada fakta tersedia)'}
SUMBER PRIMER:
${primarySources || '(tidak ada karya primer tersedia)'}
ENTITAS KUNCI: ${(outline.resolvedEntities || []).join(', ') || '(tidak ada)'}
FAQ:
${faqText}
TARGET PANJANG: ${tw} kata

=== SUARA SITUS ===
${toneText}

=== ATURAN INTEGRITAS ===
1. Jangan mengarang angka, tahun, nama tokoh/studi/organisasi, pengalaman pribadi, diagnosis, gejala, pengobatan, atau kutipan.
2. Nama dan konsep harus ada di FAKTA atau concept brief. Kutipan bertanda kutip hanya boleh verbatim dari FAKTA.
3. Wajib menyebut minimal satu karya primer yang benar-benar ada di SUMBER PRIMER dengan penulis + judul + tahun.
4. Setiap teori/konsep yang diatribusikan kepada tokoh menyebut tokohnya dalam kalimat yang sama.
5. Klaim numerik wajib memiliki markdown link sumber di kalimat/paragraf yang sama.

=== ATURAN KEDALAMAN ===
6. Ikuti logicalMove setiap section. Nyatakan perubahan pemahaman, jangan hanya menambah informasi tentang topik yang sama.
7. Jika ada scenePlan, gunakan adegan untuk GENERATE, TEST, atau LIMIT klaim. Jika adegan dihapus dan argumen tetap sama, adegan itu gagal dan harus diubah. Jangan mengarang memoir; gunakan skenario transparan bila detail personal tidak tersedia.
8. Setelah sumber disebut, lakukan kerja argumentatif: SUPPORT, TEST, NARROW, atau CONTRAST. Jangan membuat rangkuman literatur yang berhenti pada "Tokoh X berpendapat Y".
9. Transisi harus menjelaskan kenapa gerakan berikutnya diperlukan.
10. Keberatan harus kuat dan jujur; akui concession dan tunjukkan apakah tesis SURVIVES, NARROWS, atau CHANGES.
11. Jangan mengulang sectionClaim dengan contoh baru.
12. Pembuka boleh memakai adegan, pengamatan, atau ketegangan; tidak harus menjawab heading. Penutup wajib menghasilkan CLOSING DELTA, bukan rangkuman atau ajakan generik.
13. Jangan memakai tabel, emoji, sisipan berlabel seperti "Kalimat penentu:", atau definisi kamus berulang.
14. Gunakan orang kedua hanya jika konkret dan tidak mengklaim isi kepala pembaca.
15. FAQ setelah penutup, dengan jawaban 40-70 kata.
16. Format struktur wajib: tulis pembuka tanpa heading, lalu keluarkan tepat satu heading Markdown ## untuk setiap section di OUTLINE DAN LOGICAL MOVE menggunakan judul heading yang sama atau sangat dekat. Jangan gabungkan atau menghilangkan section. Setelah seluruh section dan penutup, keluarkan ## FAQ dan pertanyaan FAQ sebagai ###.
17. Sebelum metadata, pastikan artikel memiliki minimal tiga heading ## selain ## FAQ, dan urutan heading mengikuti OUTLINE.
18. Output hanya Markdown artikel lalu ---METADATA--- dan JSON metadata yang valid.`;
return [{ json: { _writerBody: { model: 'gpt-5.4-nano', messages: [{ role: 'system', content: `Kamu adalah penulis esai reflektif. Ikuti kontrak argumen dan integritas dengan ketat.

TONE SITUS:
${toneText}` }, { role: 'user', content: prompt }], max_tokens: Math.ceil(tw * 2.2) + 2500, temperature: 0.65 } } }];

const raw = $json.choices?.[0]?.message?.content || '';
function tryParse(v) {
  if (v && typeof v === 'object' && !Array.isArray(v)) return v;
  let t = String(v || '').replace(/```json?/gi,'').replace(/```/g,'').trim();
  const s = t.indexOf('{'); const e = t.lastIndexOf('}');
  if (s !== -1 && e !== -1 && e > s) t = t.substring(s, e + 1);
  try { return JSON.parse(t); } catch(e) { return null; }
}
const parsed = tryParse(raw);
const facts = Array.isArray(parsed?.facts) ? parsed.facts : [];
const commonQuestions = Array.isArray(parsed?.commonQuestions) ? parsed.commonQuestions : [];
const entities = Array.isArray(parsed?.entities) ? parsed.entities : [];
const notes = parsed?.notes || '';
return [{ json: { facts, commonQuestions, entities, notes, parseOk: facts.length > 0 } }];

const d = $input.first().json;
const researchRan = d.researchRan !== false;

if (!researchRan) {
  const cb = d.conceptBrief || {};
  const seeds = (cb.sectionSeeds || []).length;
  const thinkers = (cb.thinkers || []).length;
  if (seeds < 5 || thinkers < 1) throw new Error(`Concept-only validation FAIL: sectionSeeds ${seeds}/5, thinkers ${thinkers}/1`);
  return [{ json: { ...d, _validated: true } }];
}

const brief = $('Code: Parse Concept Brief').first().json || {};
const claimsRequested = Math.max(1, (brief.empiricalClaims || []).length);
const minFacts = claimsRequested;
const minNumeric = Math.min(claimsRequested, 1);
const numericFacts = (d.facts || []).filter(f => f.hasNumber && f.sourceUrl);
const factCount = (d.facts || []).length;
const numericCount = numericFacts.length;
if (factCount < minFacts || numericCount < minNumeric) {
  throw new Error(`Validate Research: FAIL — facts ${factCount}/${minFacts}, numeric+source ${numericCount}/${minNumeric}`);
}
return [{ json: { ...d, _validated: true, _factCount: factCount, _numericCount: numericCount } }];

const ctx = $('Code: Build Run Context').first().json;
const research = $input.first().json;
const facts = research.facts || [];
const commonQuestions = research.commonQuestions || [];
const factsList = facts.map((f,i) => `${i+1}. ${f.claim} ${f.value ? '(' + f.value + ')' : ''} — ${f.sourceName}`).join('\n');
const cb = research.conceptBrief || {};
const angle = cb.angle || '';
const sectionSeeds = Array.isArray(cb.sectionSeeds) ? cb.sectionSeeds.map(s => `- ${s.question} (${s.evidenceType})`).join('\n') : '';
const questionsList = commonQuestions.join(', ');
const language = ctx.language || 'Indonesia';
const prompt = `BAHASA ARTIKEL: ${language}. Tulis outline dan seluruh field teks dalam Bahasa ${language}. Jangan menerjemahkan istilah teknis/filosofis tanpa padanan baku, nama resmi teori, atau kutipan verbatim.

Kamu adalah content strategist yang menyusun satu argumen artikel, bukan daftar jawaban untuk chatbot.

TOPIK: ${ctx.topic}
DETAIL TOPIK: ${ctx.topicDetail || ''}
TARGET KEYWORD: ${ctx.targetKeyword || ''}
ENTITAS WAJIB: ${ctx.keyEntitiesSeed || ''}
FAQ SEED: ${ctx.faqSeed || ''}
TARGET PANJANG: ${ctx.wordCountTarget || 'Auto'}
FAKTA TERSEDIA: ${factsList}
PERTANYAAN UMUM: ${questionsList}
ANGLE: ${angle}
ARGUMENT PATTERN: ${cb.argumentPattern || ''}
PATTERN RATIONALE: ${cb.patternRationale || ''}
EXPECTED INSIGHT: ${cb.expectedInsight || ''}
SECTION SEEDS:
${sectionSeeds}
TONE: ${JSON.stringify(ctx.contentContext?.tone || {})}

ATURAN OUTLINE:
1. Buat TEPAT 5 H2 isi, lalu FAQ sebagai section terakhir. Jangan keluarkan 4 atau 6; hitung array sections sebelum mengakhiri JSON. Maksimal 2 heading isi boleh berbentuk pertanyaan; sisanya heading tematik.
