function escapeHtml(s) {
  return String(s || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function inlineFormat(text) {
  let out = escapeHtml(text);
  out = out.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
  out = out.replace(/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g, '<a href="$2">$1</a>');
  return out;
}

function convertTable(lines) {
  const rows = lines.map(l => l.trim().replace(/^\||\|$/g, '').split('|').map(c => c.trim()));
  const header = rows[0];
  const bodyRows = rows.slice(2);
  let html = '<table><tr>' + header.map(h => `<th>${inlineFormat(h)}</th>`).join('') + '</tr>';
  for (const r of bodyRows) {
    html += '<tr>' + r.map(c => `<td>${inlineFormat(c)}</td>`).join('') + '</tr>';
  }
  html += '</table>';
  return html;
}

function convertMarkdownToHtml(md) {
  const lines = md.split('\n');
  let html = '';
  let i = 0;
  let listBuffer = [];
  let listType = null;

  function flushList() {
    if (listBuffer.length) {
      html += `<${listType}>` + listBuffer.map(li => `<li>${inlineFormat(li)}</li>`).join('') + `</${listType}>`;
      listBuffer = [];
      listType = null;
    }
  }

  while (i < lines.length) {
    const line = lines[i];
    const trimmed = line.trim();

    if (!trimmed) { flushList(); i++; continue; }

    let m;
    if ((m = trimmed.match(/^####\s+(.+)/))) { flushList(); html += `<h4>${inlineFormat(m[1])}</h4>`; i++; continue; }
    if ((m = trimmed.match(/^###\s+(.+)/))) { flushList(); html += `<h3>${inlineFormat(m[1])}</h3>`; i++; continue; }
    if ((m = trimmed.match(/^##\s+(.+)/))) { flushList(); html += `<h2>${inlineFormat(m[1])}</h2>`; i++; continue; }
    if ((m = trimmed.match(/^#\s+(.+)/))) { flushList(); html += `<h1>${inlineFormat(m[1])}</h1>`; i++; continue; }

    if ((m = trimmed.match(/^>\s?(.*)/))) { flushList(); html += `<blockquote>${inlineFormat(m[1])}</blockquote>`; i++; continue; }

    if (trimmed.startsWith('|') && lines[i + 1] && /^\s*\|[\s:|-]+\|\s*$/.test(lines[i + 1])) {
      flushList();
      const tableLines = [trimmed, lines[i + 1].trim()];
      let j = i + 2;
      while (j < lines.length && lines[j].trim().startsWith('|')) { tableLines.push(lines[j].trim()); j++; }
      html += convertTable(tableLines);
      i = j;
      continue;
    }

    if ((m = trimmed.match(/^[-*+]\s+(.+)/))) {
      if (listType !== 'ul') { flushList(); listType = 'ul'; }
      listBuffer.push(m[1]);
      i++;
      continue;
    }

    if ((m = trimmed.match(/^\d+\.\s+(.+)/))) {
      if (listType !== 'ol') { flushList(); listType = 'ol'; }
      listBuffer.push(m[1]);
      i++;
      continue;
    }

    flushList();
    html += `<p>${inlineFormat(trimmed)}</p>`;
    i++;
  }
  flushList();
  return html;
}

