const draft = $('Code: Parse Draft').first().json?.draft || '';
const warnings = [];
function esc(v) { return String(v || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function inline(v) { return esc(v).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>').replace(/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g,'<a href="$2">$1</a>'); }
function cells(v) { return v.trim().replace(/^\||\|$/g,'').split('|').map(x => x.trim()).filter(Boolean); }
function convert(md) {
  const lines = String(md).split(/\r?\n/), out = [];
  let paragraph = [], list = null;
  const flushParagraph = () => { if (paragraph.length) { out.push(`<p>${inline(paragraph.join(' '))}</p>`); paragraph = []; } };
  const flushList = () => { if (list) { out.push(`<${list.type}>${list.items.map(x => `<li>${inline(x)}</li>`).join('')}</${list.type}>`); list = null; } };
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) { flushParagraph(); flushList(); continue; }
    if (line === '---METADATA---') break;
    if (line.startsWith('|') && lines[i + 1] && /^\s*\|[\s:|-]+\|\s*$/.test(lines[i + 1])) {
      flushParagraph(); flushList(); warnings.push('Markdown table removed by WordPress renderer');
      const rows = [line, lines[++i].trim()]; while (i + 1 < lines.length && lines[i + 1].trim().startsWith('|')) rows.push(lines[++i].trim());
      const text = rows.filter(x => !/^\s*\|[\s:|-]+\|\s*$/.test(x)).map(x => cells(x).join(' - ')).join('. ');
      if (text) out.push(`<p>${inline(text)}</p>`); continue;
    }
    let m;
    if ((m = line.match(/^###\s+(.+)/))) { flushParagraph(); flushList(); out.push(`<h3>${inline(m[1])}</h3>`); continue; }
    if ((m = line.match(/^##\s+(.+)/))) { flushParagraph(); flushList(); out.push(`<h2>${inline(m[1])}</h2>`); continue; }
    if ((m = line.match(/^#\s+(.+)/))) { flushParagraph(); flushList(); warnings.push('Markdown H1 omitted; WordPress title is the H1'); continue; }
    if ((m = line.match(/^>\s?(.*)/))) { flushParagraph(); flushList(); out.push(`<blockquote><p>${inline(m[1])}</p></blockquote>`); continue; }
    if ((m = line.match(/^[-*+]\s+(.+)/))) { flushParagraph(); if (!list || list.type !== 'ul') { flushList(); list = {type:'ul',items:[]}; } list.items.push(m[1]); continue; }
    if ((m = line.match(/^\d+\.\s+(.+)/))) { flushParagraph(); if (!list || list.type !== 'ol') { flushList(); list = {type:'ol',items:[]}; } list.items.push(m[1]); continue; }
    flushList(); paragraph.push(line);
  }
  flushParagraph(); flushList(); return out.join('\n');
}
return [{json:{_wpHtml:convert(draft),_wpRenderWarnings:warnings}}];

